-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["c504a9c4fc369701"] = { "Eppure, mentre passavano ere apparentemente infinite, la civiltà degli elfi della notte si espanse sia nel territorio sia nella cultura. I loro templi, le loro strade e le loro dimore si estendevano per tutto l'oscuro continente. Azshara, la bella e dotata regina degli elfi della notte, costruì sulle rive del Pozzo un immenso, meraviglioso palazzo che ospitava i suoi servitori prediletti nelle sue sale ingioiellate.", "." },
  ["c53e5ace79b40598"] = { "A quel punto il Flagello dei non morti aveva ormai trasformato Lordaeron e Quel'Thalas nelle tossiche ⟦Plaguelands=Terre Infette⟧. Restavano solo poche sacche di resistenza dell'⟦Alliance=Alleanza⟧. Uno di questi gruppi, composto soprattutto da alti elfi, era guidato dall'ultimo della dinastia Sunstrider: il principe Kael'thas.", "." },
  ["c558f5399228c1b9"] = { "Carissima Amelia,\n\nstanotte ho visto cose che mi perseguiteranno fino alla fine dei tempi.\n\nStratholme è in fiamme... e la colpa è nostra.\n\nStanotte il nostro principe ci ha guidati per le strade della città; ci ha ordinato di fare irruzione nelle case degli abitanti e... di ucciderli nel sonno. Erano appestati, sosteneva lord Arthas, e dovevano essere uccisi prima che uccidessero noi.\n\nÈ stato un massacro. Centinaia di persone sono morte in silenzio sotto le spade di chi aveva giurato di proteggerle. Non ce l'ho fatta più; sono fuggito.\n\nSarò anche un disertore, ma non potevo commettere simili atrocità. In ogni casa non potevo fare a meno di vedere il tuo volto, o quello dei nostri figli, sulle vittime mentre morivano. Se oppormi a tutto questo significa essere un traditore, allora così sia.\n\nSpero di riuscire a tornare da te, prima o poi, ma le strade non sono sicure. Abbraccia i nostri figli da parte mia finché sono lontano.\n\nJames", "." },
  ["c5652108904e6e83"] = { "Neltharion:\n\rNeltharion, chiamato il Custode della Terra al momento della sua creazione, era più leale e protettivo verso Azeroth di qualsiasi altro Aspetto. Il suo Stormo dei Draghi Neri fu responsabile della creazione delle montagne e delle altre forme delle terre, compresi i confini tra le razze mortali. Cosa abbia causato la sua corruzione resta ancora un mistero: un'influenza esterna o qualcosa che è marcito dall'interno. Mi chiedo se gli Dei Antichi non abbiano avuto un ruolo nella corruzione del grande drago nero.", "." },
  ["c5670351811bde57"] = { "Su Draenor, Turalyon e Khadgar accettarono di compiere l'estremo sacrificio distruggendo il Portale Oscuro dal loro lato. Anche se sarebbe costato la loro vita e quella dei loro compagni, sapevano che era l'unico modo per garantire la sopravvivenza di Azeroth. Proprio mentre Hellscream e Deadeye si aprivano a colpi d'ascia un varco tra le file umane, nel disperato tentativo di conquistare la libertà, il Portale Oscuro esplose alle loro spalle. Per loro, e per gli orchi rimasti su Azeroth, non ci sarebbe stato ritorno.", "." },
  ["c56f8358b488455b"] = { "Lo stato del culto, volume 92\n\nÈ con cuore gioioso che vi saluto, fratelli miei, perché lo stato del nostro culto non potrebbe essere più grandioso. Siamo legione, e i nostri obiettivi si avvicinano sempre più alla realizzazione.\n\nNuove reclute continuano a radunarsi. Cantano lodi ai nostri signori a ⟦Darkshore=Rivafosca⟧, si inchinano in giubilante estasi nella ⟦Searing Gorge=Gorgia Rovente⟧, accolgono il servitore dei nostri padroni, Aku'mai, negli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧. Davvero, fratelli e sorelle miei, presto uno sciame di fedeli coprirà tutta Azeroth!", "." },
})
